<?php get_header(); $term=get_queried_object(); $portrait=absint(get_term_meta($term->term_id,'gmr_artist_portrait_id',true)); $cover=absint(get_term_meta($term->term_id,'gmr_artist_cover_id',true)); ?>
<section class="gmr-term-hero"><div class="gmr-term-hero__image"><?php echo wp_get_attachment_image($cover?:$portrait,'full'); ?></div><div class="gmr-term-hero__content"><span class="gmr-kicker">Artista</span><h1><?php echo esc_html($term->name);?></h1><?php if($term->description) echo '<p>'.esc_html($term->description).'</p>';?></div></section>
<?php $bio=get_term_meta($term->term_id,'gmr_artist_biography',true); if($bio):?><section class="gmr-section"><div class="gmr-wrap gmr-editorial"><?php echo wp_kses_post(wpautop($bio));?></div></section><?php endif;?>
<section class="gmr-section gmr-section--white"><div class="gmr-wrap"><div class="gmr-section__head"><div><span class="gmr-kicker">Obras</span><h2>En la galeria</h2></div></div><?php if(have_posts()){echo '<div class="gmr-grid">';while(have_posts()){the_post();get_template_part('template-parts/artwork','card');}echo '</div>';the_posts_pagination();}else echo '<p class="gmr-empty">No hay obras visibles de este artista.</p>';?></div></section>
<?php $history=get_term_meta($term->term_id,'gmr_artist_history',true); if($history):?><section class="gmr-section"><div class="gmr-wrap gmr-editorial"><span class="gmr-kicker">Trayectoria</span><?php echo wp_kses_post(wpautop($history));?></div></section><?php endif; get_footer(); ?>
